<?php require_once __DIR__ . '/../includes/auth.php'; require_login(); ?>
<div class="table-shell" id="pig-results" aria-busy="false"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Tag</th><th>Category</th><th>Weight</th><th>Pen</th><th>Status</th><th>Date added</th><th></th></tr></thead><tbody><?php foreach ($pigs as $pig): ?><tr><td class="fw-bold"><?= e($pig['tag_number']) ?></td><td><?= e(ucfirst($pig['category'])) ?></td><td><?= e($pig['weight']) ?> kg</td><td><?= e($pig['pen_number'] ?: '—') ?></td><td><span class="chip chip-<?= $pig['status'] === 'active' ? 'success' : ($pig['status'] === 'dead' ? 'danger' : 'neutral') ?>"><?= e(ucfirst($pig['status'])) ?></span></td><td><?= e($pig['date_added']) ?></td><td class="text-end"><div class="table-actions pig-table-actions"><a class="btn btn-outline-secondary action-edit" href="edit.php?id=<?= (int) $pig['pig_id'] ?>"><i data-lucide="pencil" aria-hidden="true"></i><span>Edit</span></a><?php if ($pig['status'] === 'active'): ?><form method="post" action="delete.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="pig_id" value="<?= (int) $pig['pig_id'] ?>"><button class="btn btn-danger action-dead" data-confirm-dialog="Mark this pig as dead?"><i data-lucide="skull" aria-hidden="true"></i><span>Dead</span></button></form><?php else: ?><span class="pig-action-placeholder" aria-hidden="true"></span><?php endif; ?></div></td></tr><?php endforeach; ?><?php if (!$pigs): ?><tr><td colspan="7" class="text-center text-muted py-5">No pigs match these filters.</td></tr><?php endif; ?></tbody></table></div></div>
